const DIGITS = String.raw`\d(?:_?\d)*`;
const DECIMAL_FLOAT_PATTERN = new RegExp(
  String.raw`^[+-]?(?:` +
    String.raw`(?:${DIGITS})(?:\.(?:${DIGITS})?)?` +
    String.raw`|` +
    String.raw`\.(?:${DIGITS})` +
  String.raw`)(?:[eE][+-]?${DIGITS})?$`,
);
const NAN_PATTERN = /^[+-]?nan$/i;
const INFINITY_PATTERN = /^[+-]?(?:inf|infinity)$/i;

export class InvalidFloatError extends Error {
  constructor(token) {
    super(`argument --a: invalid float value: '${token}'`);
    this.name = "InvalidFloatError";
  }
}

export function parsePythonFloatToken(token) {
  if (NAN_PATTERN.test(token)) {
    return Number.NaN;
  }

  if (INFINITY_PATTERN.test(token)) {
    return token.startsWith("-") ? Number.NEGATIVE_INFINITY : Number.POSITIVE_INFINITY;
  }

  if (!DECIMAL_FLOAT_PATTERN.test(token)) {
    throw new InvalidFloatError(token);
  }

  return Number(token.replaceAll("_", ""));
}

const HELP_TOKENS = new Set(["-h", "--help"]);
const NEGATIVE_NUMBER_TOKEN = /^-(?:\d(?:_?\d)*|\d(?:_?\d)*\.(?:\d(?:_?\d)*)?|\.(?:\d(?:_?\d)*))$/;
const USAGE_SUFFIX = "[-h] --a A";
const OPTIONS_TEXT = "options:\n  -h, --help  show this help message and exit\n  --a A";

export class ArgparseError extends Error {
  constructor(message, exitCode = 2) {
    super(message);
    this.name = "ArgparseError";
    this.exitCode = exitCode;
  }
}

export function getProgramName(argv = process.argv) {
  const scriptPath = argv[1] ?? "test3.mjs";
  const segments = scriptPath.split(/[\\/]/);
  return segments[segments.length - 1] || "test3.mjs";
}

export function buildHelpText(programName) {
  return `usage: ${programName} ${USAGE_SUFFIX}\n\n${OPTIONS_TEXT}`;
}

export function buildArgumentErrorMessage(programName, detail) {
  return `usage: ${programName} ${USAGE_SUFFIX}\n${programName}: error: ${detail}`;
}

function isMissingOptionValue(token) {
  return token === undefined || (token.startsWith("-") && token !== "-" && !NEGATIVE_NUMBER_TOKEN.test(token));
}

function convertValue(programName, parseFloatToken, token) {
  if (parseFloatToken === undefined) {
    return token;
  }

  try {
    return parseFloatToken(token);
  } catch (error) {
    if (error instanceof Error && error.name === "InvalidFloatError") {
      throw new ArgparseError(buildArgumentErrorMessage(programName, error.message));
    }

    throw error;
  }
}

export function parseCli(argv = process.argv, { parseFloatToken } = {}) {
  const programName = getProgramName(argv);
  let a;
  let hasA = false;
  const extras = [];

  for (let index = 2; index < argv.length; index += 1) {
    const token = argv[index];

    if (HELP_TOKENS.has(token)) {
      return { kind: "help", programName, text: buildHelpText(programName) };
    }

    if (token === "--") {
      extras.push(...argv.slice(index + 1));
      break;
    }

    if (token === "--a") {
      const valueToken = argv[index + 1];
      if (isMissingOptionValue(valueToken)) {
        throw new ArgparseError(buildArgumentErrorMessage(programName, "argument --a: expected one argument"));
      }

      a = convertValue(programName, parseFloatToken, valueToken);
      hasA = true;
      index += 1;
      continue;
    }

    if (token.startsWith("--a=")) {
      a = convertValue(programName, parseFloatToken, token.slice(4));
      hasA = true;
      continue;
    }

    extras.push(token);
  }

  if (!hasA) {
    throw new ArgparseError(buildArgumentErrorMessage(programName, "the following arguments are required: --a"));
  }

  if (extras.length > 0) {
    throw new ArgparseError(buildArgumentErrorMessage(programName, `unrecognized arguments: ${extras.join(" ")}`));
  }

  return { kind: "run", programName, a };
}

export class ValueError extends Error {
  constructor(message) {
    super(message);
    this.name = "ValueError";
  }
}

function describeNonFinite(value) {
  if (Number.isNaN(value)) {
    return "nan";
  }

  return value < 0 ? "-inf" : "inf";
}

function decomposeNumberString(raw) {
  let text = raw;
  let sign = "";

  if (text.startsWith("-")) {
    sign = "-";
    text = text.slice(1);
  }

  let digits;
  let decimalPower;
  const exponentMarker = text.toLowerCase().indexOf("e");

  if (exponentMarker !== -1) {
    const mantissa = text.slice(0, exponentMarker);
    const exponent = Number.parseInt(text.slice(exponentMarker + 1), 10);
    const dotIndex = mantissa.indexOf(".");

    if (dotIndex === -1) {
      digits = mantissa;
      decimalPower = exponent;
    } else {
      const integerPart = mantissa.slice(0, dotIndex);
      const fractionalPart = mantissa.slice(dotIndex + 1);
      digits = integerPart + fractionalPart;
      decimalPower = exponent - fractionalPart.length;
    }
  } else {
    const dotIndex = text.indexOf(".");

    if (dotIndex === -1) {
      digits = text;
      decimalPower = 0;
    } else {
      const integerPart = text.slice(0, dotIndex);
      const fractionalPart = text.slice(dotIndex + 1);
      digits = integerPart + fractionalPart;
      decimalPower = -fractionalPart.length;
    }
  }

  digits = digits.replace(/^0+/, "");
  if (digits === "") {
    return { sign, digits: "0", decimalPower: 0 };
  }

  const trailingZeros = digits.match(/0+$/);
  if (trailingZeros !== null) {
    const zeroCount = trailingZeros[0].length;
    digits = digits.slice(0, digits.length - zeroCount);
    decimalPower += zeroCount;
  }

  return { sign, digits, decimalPower };
}

export function formatPythonFloat(value) {
  if (!Number.isFinite(value)) {
    throw new ValueError(`Out of range float values are not JSON compliant: ${describeNonFinite(value)}`);
  }

  if (Object.is(value, -0)) {
    return "-0.0";
  }

  if (value === 0) {
    return "0.0";
  }

  const { sign, digits, decimalPower } = decomposeNumberString(value.toString());
  const decimalExponent = decimalPower + digits.length - 1;

  if (decimalExponent < -4 || decimalExponent >= 16) {
    const fractionalDigits = digits.length > 1 ? `.${digits.slice(1)}` : "";
    const exponentSign = decimalExponent >= 0 ? "+" : "-";
    const exponentMagnitude = String(Math.abs(decimalExponent)).padStart(2, "0");
    return `${sign}${digits[0]}${fractionalDigits}e${exponentSign}${exponentMagnitude}`;
  }

  if (decimalPower >= 0) {
    return `${sign}${digits}${"0".repeat(decimalPower)}.0`;
  }

  const pointIndex = digits.length + decimalPower;
  if (pointIndex > 0) {
    return `${sign}${digits.slice(0, pointIndex)}.${digits.slice(pointIndex)}`;
  }

  return `${sign}0.${"0".repeat(-pointIndex)}${digits}`;
}

export {
  ArgparseError,
  buildArgumentErrorMessage,
  buildHelpText,
  getProgramName,
  parseCli,
} from "./argparse.mjs";
export { InvalidFloatError, parsePythonFloatToken } from "./float_parser.mjs";
export { ValueError, formatPythonFloat } from "./float_repr.mjs";
export { encodeCanonicalJson, formatBytesLiteral } from "./canonical_json.mjs";

import { formatPythonFloat } from "./float_repr.mjs";

const textEncoder = new TextEncoder();
const textDecoder = new TextDecoder("utf-8");

export function encodeCanonicalJson(value) {
  return textEncoder.encode(formatPythonFloat(value));
}

export function formatBytesLiteral(bytes) {
  return `b'${textDecoder.decode(bytes)}'`;
}

